use vstd::prelude::*;

verus! {

/// Checks whether the grid is “disconnected” according to the
/// four corner‐based rules.
fn check_disconnected(
    n: i8,
    m: i8,
    horizontal: &Vec<char>,
    vertical: &Vec<char>,
) -> bool
    requires
        // we only use the lengths via casting to usize, so
        // we must ensure they sit in the non­negative range
        0 <= n,
        0 <= m,
        horizontal.len() == (n as usize),
        vertical.len() == (m as usize),
    ensures
        // the return value exactly matches the corner‐inspection
        // boolean formula in the body
        ret == (
            // top‐left corner pointing right & top‐edge arrow down
            (horizontal[0] == '>' && vertical[0] == 'v')
            // top‐left corner pointing left & bottom‐edge arrow down
            || (horizontal[0] == '<' && vertical[(m as usize) - 1] == 'v')
            // top‐right corner pointing right & top‐edge arrow up
            || (horizontal[(n as usize) - 1] == '>' && vertical[0] == '^')
            // top‐right corner pointing left & bottom‐edge arrow up
            || (horizontal[(n as usize) - 1] == '<' && vertical[(m as usize) - 1] == '^')
        ),
{
    // Convert to usize for indexing
    let n_usize = n as usize;
    let m_usize = m as usize;

    // Optional sanity checks (can be omitted in release builds)
    debug_assert_eq!(horizontal.len(), n_usize);
    debug_assert_eq!(vertical.len(), m_usize);

    let h_first = horizontal[0];
    let h_last  = horizontal[n_usize - 1];
    let v_first = vertical[0];
    let v_last  = vertical[m_usize - 1];

    (h_first == '>' && v_first == 'v')
        || (h_first == '<' && v_last == 'v')
        || (h_last  == '>' && v_first == '^')
        || (h_last  == '<' && v_last  == '^')
}

/// Produces “NO\n” if the puzzle is disconnected,
/// otherwise “YES\n”.
fn solve(
    n: i8,
    m: i8,
    horizontal: Vec<char>,
    vertical: Vec<char>,
) -> Vec<char>
    requires
        0 <= n,
        0 <= m,
        horizontal.len() == (n as usize),
        vertical.len()   == (m as usize),
    ensures
        // if disconnected then exactly ['N','O','\n'], else ['Y','E','S','\n']
        (check_disconnected(n, m, &horizontal, &vertical)
            ==> result == vec!['N','O','\n'])
        && (!check_disconnected(n, m, &horizontal, &vertical)
            ==> result == vec!['Y','E','S','\n']),
{
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}

} // end verus!

fn main() {
    let n = 4;
    let m = 3;
    let horizontal = vec!['<', '<', '>', '>'];
    let vertical   = vec!['^', 'v', 'v'];

    let result = solve(n, m, horizontal, vertical);
    let output: String = result.into_iter().collect();
    print!("{}", output);
}